from core import *

def cube_net():
 cells={(0,1):1,(1,1):2,(2,1):3,(3,1):4,(1,0):5,(1,2):6}
 return svg(''.join(f'<rect x="{60+65*x}" y="{20+65*y}" width="65" height="65" fill="#f1e5c4"/>'+text(92.5+65*x,61+65*y,n) for (x,y),n in cells.items()),h=235,label='Cube net: row 1,2,3,4; face 5 above face 2; face 6 below face 2.')

def papers():
 p=[]
 p.append(item('Calculate 6.25 × 16.',100,'Since 16=4×4, multiply in two stages: 6.25×4=25, then 25×4=100.','DIG-01',[25,64,96,104],check=6.25*16))
 p.append(item('A study club meets from 3:35 pm until 5:05 pm. It takes two breaks of 8 minutes each. How many minutes are spent working?',74,'The full interval lasts 90 minutes. The breaks total 16 minutes, leaving 90−16=74 working minutes.','RATE-01',[66,72,76,82],check=90-2*8))
 p.append(item('Thirty-five students study French, 28 study Japanese, and 12 study both. Seven study neither. How many students are there altogether?',58,'The language groups together contain 35+28−12=51 distinct students. Add the seven outside both groups to get 58.','COUNT-04',[44,51,63,70],check=35+28-12+7))
 p.append(item('The first four square numbers are 1, 4, 9 and 16. What is the difference between the 12th and 11th square numbers?',23,'The numbers are 12²=144 and 11²=121, whose difference is 23. The difference of consecutive squares n²−(n−1)² is 2n−1.','SEQ-01',[21,22,24,25],check=12**2-11**2))
 p.append(item('A triangle symbol plus a circle is 13. A circle plus a square is 17. A triangle plus a square is 20. What is the square’s value?',12,'Add the second and third equations and subtract the first: two squares equal 17+20−13=24. One square is 12. Then circle=5 and triangle=8 check all three clues.','ALG-03',[5,8,10,15],check=(17+20-13)//2))
 p.append(item('In a fruit box, apples and pears are in the ratio 7:4. There are 18 more apples than pears. How many pieces of fruit are in the box?',66,'The difference is three ratio parts, so each part is 18÷3=6 fruit. The total eleven parts contain 11×6=66 fruit.','FRAC-02',[42,48,60,72],check=18//3*11))
 p.append(item('The digits 0, 2, 4 and 6 are used once each to make a four-digit number divisible by 5. How many numbers are possible?',6,'Divisibility by 5 forces the last digit to be 0. The remaining three nonzero digits can be placed in 3×2×1=6 ways; every such arrangement has a valid leading digit.','DIG-02',[3,9,12,18],check=math.factorial(3)))
 p.append(item('The net is folded to make a cube. Which numbered face is opposite face 2?',4,'Faces 1 and 3 fold up on opposite sides of face 2. Face 4 folds once more from face 3 and becomes the face across from 2. The other opposite pair is 5 and 6.','GEO-04',[1,3,5,6],figure=cube_net()))
 p.append(item('Six identical machines complete a batch in 10 hours. At the same constant rate, how many hours do fifteen machines need for the same batch?',4,'The batch requires 6×10=60 machine-hours. Fifteen machines provide fifteen machine-hours per hour, so the job takes 60÷15=4 hours.','RATE-02',[3,5,6,25],check=6*10//15))
 p.append(item('A museum sells 38 tickets. Adult tickets cost $12 and child tickets $7. The total received is $356. How many adult tickets were sold?',18,'If all tickets were children’s, the total would be 38×7=$266. Adults add $5 each, so the extra $90 comes from 90÷5=18 adult tickets.','ALG-03',[16,17,19,20],check=(356-38*7)//5))
 p.append(item('The four-letter string ABAB is rotated one character to the right every second. How many times does it show ABAB again during the first 30 seconds, excluding time zero?',15,'ABAB returns after two rotations, because AB repeats. Returns occur at seconds 2,4,…,30, giving 30÷2=15 occurrences.','DIV-05',[7,8,14,30],check=30//2))
 p.append(item('A hire service charges $14 for up to 90 minutes, then $6 for each additional hour or part of an hour. What is the cost of hiring for 4 hours?','$32','Four hours is 240 minutes. After the included 90 minutes, 150 remain. That uses three hourly charging blocks, so the cost is 14+3×6=$32.','RATE-01',['$26','$29','$35','$38']))
 p.append(item('A regular pentagon has interior angles of 108°. Two identical regular pentagons meet at a vertex without overlapping. What angle remains around that vertex?', '144°','A full turn is 360°. The two pentagons occupy 108°+108°=216°, leaving 360°−216°=144°.','GEO-03',['72°','108°','132°','216°']))
 p.append(item('The row totals of a 3-by-4 number grid are 27, 35 and 42. Three column totals are 18, 24 and 31. What is the fourth column total?',31,'Both sets of totals count every cell once. The row totals sum to 104; the known columns sum to 73. The missing total is 104−73=31.','LOGIC-03',[27,29,33,35],check=27+35+42-18-24-31))
 p.append(item('Ten students have a mean score of 16. Five other students have a mean score of 22. What is the combined mean?',18,'The group totals are 10×16=160 and 5×22=110. The combined total 270 is shared by 15 students, giving mean 270÷15=18. The unequal group sizes mean we cannot simply average 16 and 22.','DATA-02',[17,19,20,21],check=(10*16+5*22)//15))
 p.append(item('A 14 cm by 10 cm rectangle contains a triangle with the full 14 cm bottom edge as base and its third vertex anywhere on the opposite edge. What area of the rectangle lies outside the triangle?', '70 cm²','Every point on the opposite edge has perpendicular height 10 cm above the base. The triangle’s area is 14×10÷2=70 cm², exactly half the rectangle. The other half is also 70 cm².','GEO-02',['35 cm²','56 cm²','84 cm²','105 cm²'],figure=svg('<rect x="60" y="25" width="280" height="200" fill="#f1e5c4"/><polygon points="60,225 340,225 150,25" fill="white"/>'+text(215,245,'14 cm')+text(370,125,'10 cm'),h=260)))
 p.append(item('A number consists of ten digits, all 8. What is the digit sum after adding 1111111112?',1,'The ten-digit number 8888888888 plus 1111111112 equals 10000000000. Only its leading 1 contributes to the digit sum, so the sum is 1. Recognise the complementary digits and final carry.','DIG-04',[10,80,90,100],check=sum(map(int,str(8888888888+1111111112)))))
 p.append(item('Exactly one of three statements about a positive integer N is true: “N is even”; “N is divisible by 3”; “N is 8”. Which listed value could N be?',14,'Test each candidate against all three statements. For 14 only “even” is true. For 6 and 12 the first two are true; for 8 the first and third are true; for 5 none is true. Thus 14 is the sole valid option.','LOGIC-01',[6,8,12,5]))
 p.append(item('In a group of 60, 32 play chess, 28 play tennis and 24 play music. The pairwise overlaps, including anyone in all three, are 12, 10 and 8. Six do all three. How many do none of the activities?',0,'Inclusion–exclusion gives the union as 32+28+24−12−10−8+6=60. Pairwise overlaps subtract all-three members three times after they were added three times, so add them once to keep one copy. All 60 do an activity, leaving none.','COUNT-04',check=60-(32+28+24-12-10-8+6)))
 p.append(item('Two runners circle a track in the same direction. Their lap times are 9 and 15 minutes. How many minutes after starting together does the faster runner first gain two full laps?',45,'The gain rate is 1/9−1/15=2/45 lap per minute. Gaining two laps takes 2÷(2/45)=45 minutes.','RATE-04',check=int(2/(F(1,9)-F(1,15)))))
 p.append(item('A, B and C are different nonzero digits. AB, BC and CA are two-digit numbers whose sum is 198. Also B=A+2 and C=2A. What is the three-digit number ABC?',468,'The sum AB+BC+CA is 11(A+B+C), so A+B+C=18. Substitute B=A+2 and C=2A: 4A+2=18, giving A=4,B=6,C=8. Therefore ABC=468; 46+68+84=198 checks the condition.','DIG-05',check=468))
 p.append(item('A block is 4 cubes wide, 7 deep and 5 high. It is painted on all six outer faces and separated into unit cubes. How many small cubes have paint on exactly one face?',62,'Count face interiors and exclude every edge. The two 4×7 faces contribute 2×(4−2)(7−2)=20; the two 4×5 faces contribute 12; the two 7×5 faces contribute 30. Total 20+12+30=62. These categories do not overlap.','SOLID-02',check=2*((4-2)*(7-2)+(4-2)*(5-2)+(7-2)*(5-2)),figure=cuboid(4,7,5)))
 p.append(item('A charity gives away one third of its food parcels, then one quarter of what remains. Nine more parcels arrive, and there are now 54. How many parcels were there initially?',90,'Before the arrival, 54−9=45 remained. The retained fraction was (2/3)(3/4)=1/2, so the initial number was 90. Check: 90→60→45→54.','FRAC-01',check=int(F(54-9)/(F(2,3)*F(3,4)))))
 one=paper('rossmoyne',4,p)
 p=[]
 p.append(item('Calculate (7.8 + 4.2) ÷ 0.6.',20,'First add inside the brackets to get 12. Then 12÷0.6=120÷6=20.','DIG-01',[2,12,18,24],check=120//6))
 p.append(item('A book has pages numbered from 1 to 120. How many pages have a number ending in 7?',12,'The page numbers are 7,17,27,…,117. This is one number in each group of ten pages, giving twelve pages.','DIG-03',[11,13,20,21],check=sum(n%10==7 for n in range(1,121))))
 p.append(item('A cook uses 3.6 kg of flour to make 48 equal batches. How many grams of flour go into each batch?',75,'Convert 3.6 kg to 3600 g. Then divide by 48: 3600÷48=75 g per batch.','RATE-01',[60,72,80,90],check=3600//48))
 p.append(item('A club has 46 members. Twenty-nine use the pool, 24 use the gym and 8 use neither. How many use both?',15,'The union contains 46−8=38 members. Adding pool and gym counts gives 53, so the overlap is 53−38=15.','COUNT-04',[7,9,17,21],check=29+24-(46-8)))
 p.append(item('A pattern of tiles has 4 tiles in its first design. Each new design adds 7 tiles. Which design first has more than 100 tiles?',15,'Design n has 4+7(n−1) tiles. Design 14 has 95; design 15 has 102. Thus the first design beyond 100 is number 15.','SEQ-01',[13,14,16,17],check=next(n for n in range(1,30) if 4+7*(n-1)>100)))
 p.append(item('A large parcel weighs as much as two small parcels plus 3 kg. Three large parcels weigh 33 kg. What does one small parcel weigh?',4,'Each large parcel weighs 33÷3=11 kg. Removing the extra 3 kg leaves 8 kg for two small parcels, so each small parcel weighs 4 kg.','ALG-02',[3,5,6,7],check=(33//3-3)//2))
 p.append(item('The digits 1, 2, 5 and 8 are used once each to make a four-digit odd number. How many such numbers are there?',12,'The units digit must be 1 or 5, giving two choices. Arrange the other three digits in 3!=6 ways. Total 2×6=12.','DIG-02',[6,8,16,24],check=2*math.factorial(3)))
 p.append(item('What is the remainder when 3⁴⁴ is divided by 10?',1,'The last digits of powers of 3 cycle 3,9,7,1. Since 44 is divisible by 4, choose the fourth member, 1.','DIV-05',[3,5,7,9],check=pow(3,44,10)))
 p.append(item('A factory’s two lines produce equal-quality parts. One line produces 24 parts per hour and the other 36. Together they make 270 parts. How many hours did they run?',4.5,'The combined rate is 24+36=60 parts per hour. Time is 270÷60=4.5 hours.','RATE-02',[3.5,4,5,5.5],check=270/60))
 p.append(item('A date is six days before the day that is seventeen days after Friday 3 April. What date is it?','Tuesday 14 April','The net offset is 17−6=11 days. Eleven days after 3 April is 14 April, and an 11-day weekday change is four days, Friday→Tuesday.','DIV-05',['Monday 13 April','Wednesday 15 April','Thursday 16 April','Friday 17 April']))
 p.append(item('A 30-minute timer and a 42-minute timer are started together. How many complete runs does the shorter timer make before they next finish a run together?',7,'Their common finish interval is lcm(30,42)=210 minutes. The shorter timer completes 210÷30=7 runs in that interval, including its run ending at the simultaneous finish.','DIV-02',[5,6,10,14],check=math.lcm(30,42)//30))
 p.append(item('A ferry charges $9 for a bicycle plus rider. Each additional full or partial 5 kg of luggage above the included 10 kg costs $2. What is charged for bicycle, rider and 28 kg of luggage?','$17','The chargeable luggage is 28−10=18 kg. This uses four 5 kg blocks. Add $8 to the basic $9 fare to obtain $17.','RATE-01',['$15','$16','$18','$21']))
 p.append(item('Two identical rectangles, each 11 cm by 4 cm, are joined along a full side. What is the smallest possible perimeter of the joined shape?', '38 cm','Their separate perimeters total 60 cm. To minimise the outside perimeter, share the longer 11 cm side, which removes 22 cm of counted boundary. The minimum is 60−22=38 cm.','GEO-01',['30 cm','44 cm','52 cm','60 cm']))
 p.append(item('Three consecutive odd numbers sum to 171. What is the product of the smallest and largest?',3245,'The middle number is the mean, 171÷3=57. The others are 55 and 59. Their product is (57−2)(57+2)=57²−4=3249−4=3245.','ALG-01',[3135,3249,3363,3481],check=55*59))
 p.append(item('A team’s average score in its first four matches is 21. After a fifth match, its average is 24. What is the fifth score?',36,'The first four total 84. All five total 120, so the fifth score is 120−84=36. The extra match raises the average because it exceeds 24.','DATA-02',[27,30,33,39],check=5*24-4*21))
 p.append(item('A square is split by both diagonals into four triangles. One triangle is shaded. A second identical square has half its area shaded. The two squares do not overlap. What fraction of their combined area is shaded?','3/8','Use one square as an area unit. The shaded total is 1/4+1/2=3/4 of one square, while the full area is two squares. Thus the fraction is (3/4)÷2=3/8.','FRAC-04',['1/4','1/3','1/2','3/4'],check=str((F(1,4)+F(1,2))/2)))
 p.append(item('A rope traces three sides of a 24 cm by 18 cm rectangle, starting at the top-left corner and finishing at the bottom-left corner via both right-hand corners. How much longer is the rope than the straight distance between its ends?', '48 cm','The traced path is 24+18+24=66 cm. Its ends are 18 cm apart, so the excess is 66−18=48 cm. The two horizontal traverses account for the entire excess.','GEO-01',['24 cm','30 cm','42 cm','66 cm']))
 p.append(item('A number has twenty digits, all 2. What is the digit sum when it is divided by 2?',20,'Dividing 222…222 by 2 gives twenty digits, all 1, with no borrowing or carrying. Their digit sum is 20.','DIG-04',[10,18,22,40],check=sum(map(int,str(int('2'*20)//2)))))
 p.append(item('A hall contains 12 round tables with 6 people at each and 9 rectangular tables with 8 people at each. One quarter of all attendees are children. How many adults are present?',108,'The attendance is 12×6+9×8=72+72=144. Adults make up three quarters, so their number is 144×3÷4=108.','FRAC-04',check=(12*6+9*8)*3//4))
 p.append(item('Three ribbons have lengths 126 cm, 168 cm and 210 cm. They are cut into equal-length pieces with no waste, using the greatest possible piece length. How many pieces are obtained altogether?',12,'The greatest common divisor of the three lengths is 42 cm. The piece counts are 126÷42=3, 168÷42=4 and 210÷42=5, totalling 12.','DIV-02',check=(126+168+210)//math.gcd(126,math.gcd(168,210))))
 p.append(item('A and B are different nonzero digits. The four-digit numbers ABAB and BABA differ by 2727, with ABAB the larger. Also A×B=18. What is ABAB?',6363,'Place value gives ABAB−BABA=909(A−B)=2727, so A−B=3. The digit pair with difference 3 and product 18 is A=6,B=3. Thus ABAB=6363, and 6363−3636=2727.','DIG-05',check=next(1010*a+101*b for a in range(1,10) for b in range(1,10) if 909*(a-b)==2727 and a*b==18)))
 p.append(item('A cuboid is 5 cubes wide, 6 deep and 7 high. Only the four vertical sides are painted. How many cubes have no paint?',84,'The unpainted cubes avoid the left, right, front and back faces but may lie at any height, because top and bottom are not painted. Their count is (5−2)(6−2)×7=3×4×7=84.','SOLID-02',check=(5-2)*(6-2)*7,figure=cuboid(5,6,7)))
 p.append(item('Two fifths of a collection are stamps from Asia. One third of the remainder are from Europe. The other 84 stamps are from elsewhere. How many stamps are in the collection?',210,'After Asia’s two fifths, three fifths remain. Two thirds of this remainder are neither Asia nor Europe, so the 84 stamps form (3/5)(2/3)=2/5 of the whole. The total is 84×5÷2=210.','FRAC-01',check=int(F(84)/(F(3,5)*F(2,3)))))
 two=paper('rossmoyne',5,p)
 p=[]
 p.append(item('Calculate 45.6 − 8.75 + 2.4.','39.25','Combine 45.6+2.4=48 first, then subtract 8.75 to get 39.25. Addition and subtraction can be regrouped this way if the subtraction stays attached to 8.75.','DIG-01',['38.25','39.35','40.25','41.65']))
 p.append(item('A student is 8th from the left and 19th from the right in a straight line. Four students join at each end. How many students are now in the line?',34,'Initially there are 8+19−1=26 students; subtract one because the named student was counted twice. Eight more join, making 34.','COUNT-01',[33,35,36,42],check=8+19-1+8))
 p.append(item('A baker makes 72 rolls in 45 minutes at a constant rate. How many rolls are made in 2 hours 15 minutes?',216,'Two hours 15 minutes is 135 minutes, exactly three lots of 45 minutes. Therefore the baker makes 3×72=216 rolls.','RATE-01',[144,180,192,240],check=135//45*72))
 p.append(item('A survey has 90 responses. Fifty-four like hiking, 47 like cycling, and 19 like neither. How many like both?',30,'The union has 90−19=71 people. Adding the activity counts gives 101, so the overlap is 101−71=30.','COUNT-04',[11,19,24,36],check=54+47-(90-19)))
 p.append(item('A row of square tables is joined end to end. Each separate table seats four people, and each join removes two seats. How many tables are needed to seat exactly 26 people?',12,'For n tables there are n−1 joins, so the seat count is 4n−2(n−1)=2n+2. Set 2n+2=26 to obtain n=12.','ALG-01',[6,11,13,14],check=(26-2)//2))
 p.append(item('Two circles and a triangle total 23. A circle and two triangles total 25. What is the circle’s value?',7,'Subtracting shows that a triangle is 2 more than a circle. Substitute into the first sum: 3 circles+2=23, so one circle is 7 and one triangle is 9.','ALG-03',[6,8,9,11],check=(23-2)//3))
 p.append(item('Six different runners compete. How many possible ordered pairs of first and second places are there?',30,'There are six choices for first place. The winner cannot also be second, so there are five remaining choices. The total is 6×5=30.','COUNT-02',[15,20,24,36],check=6*5))
 p.append(item('What is the last digit of 6¹²³ + 4¹²⁴?',2,'Every positive power of 6 ends in 6. An even positive power of 4 also ends in 6. Their sum ends in 2, since 6+6=12.','DIV-05',[0,4,6,8],check=(pow(6,123,10)+pow(4,124,10))%10))
 p.append(item('One printer produces a booklet every 12 minutes and another every 18 minutes. Starting together, how many complete booklets have they produced after 90 minutes?',12,'The first printer completes floor(90/12)=7 booklets; its eighth is unfinished. The second completes 90/18=5. Completed booklets total 12.','RATE-02',[10,11,13,15],check=90//12+90//18))
 p.append(item('A clock shows 10:30 am. What time will it show 1000 hours and 45 minutes later?','3:15 am','The hours leave remainder 16 modulo 24, taking 10:30 am to 2:30 am the next day. Add 45 minutes to reach 3:15 am.','DIV-05',['2:15 am','2:45 am','3:15 pm','4:15 am']))
 p.append(item('Two events recur every 16 and 20 days. They happen together today. How many days until the next day on which both happen?',80,'The first common repeat is lcm(16,20). Their prime factors are 2⁴ and 2²×5, so the lcm is 2⁴×5=80 days.','DIV-02',[40,60,160,320],check=math.lcm(16,20)))
 p.append(item('A parcel service charges $12 for the first 2 kg, then $4 for each additional 500 g or part thereof. What is the charge for a 4.1 kg parcel?','$32','The extra mass is 2.1 kg=2100 g. This requires five blocks of up to 500 g. The total is 12+5×4=$32.','RATE-01',['$28','$28.80','$30','$36']))
 p.append(item('A triangle has angles in the ratio 2:3:4. What is its largest angle?', '80°','The angle ratio has nine equal parts totalling 180°, so one part is 20°. The largest angle is four parts, or 80°.','GEO-03',['40°','60°','72°','90°']))
 p.append(item('A machine adds a fixed number, then multiplies by a fixed positive whole number. Input 4 gives 30 and input 9 gives 45. What does input 12 give?',54,'The output difference 15 comes from an input difference of 5, so the multiplier is 3. Since (4+b)×3=30, b=6. Input 12 gives (12+6)×3=54.','ALG-03',[48,51,57,60],check=(12+6)*3))
 p.append(item('Three candidates receive 280 votes altogether. The winner receives 24 more than the second candidate, who receives 17 more than the third. How many votes does the winner receive?',115,'Let the winner’s count be w. The second has w−24 and the third w−41. Therefore 3w−65=280, so 3w=345 and w=115. Check 115+91+74=280.','ALG-05',[105,111,117,121],check=(280+65)//3))
 p.append(item('A rectangular floor is 8 m by 5 m. A square rug has the same perimeter as the floor. What is the rug’s area?', '42.25 m²','The floor perimeter is 2(8+5)=26 m. The square rug’s side is 26÷4=6.5 m, so its area is 6.5²=42.25 m². Equal perimeters do not force equal areas.','GEO-05',['40 m²','40.25 m²','41 m²','45 m²']))
 p.append(item('A wire runs around the boundary of a 9 cm by 7 cm rectangle. It is straightened and bent into an equilateral triangle. How long is each side of the triangle?', '32/3 cm','The wire length is the rectangle perimeter, 2(9+7)=32 cm. Bending preserves length. Three equal triangle sides therefore each have length 32÷3 cm.','GEO-01',['16/3 cm','8 cm','9 cm','12 cm']))
 p.append(item('What is the sum of the digits of 999999²?',54,'Write 999999=10⁶−1. Squaring gives 10¹²−2×10⁶+1=999998000001. The digit sum is 5×9+8+1=54.','DIG-04',[45,53,55,108],check=sum(map(int,str(999999**2)))))
 p.append(item('At a camp, 28 families each contain two adults. Three sevenths of the families bring two children; the others bring three children. How many people are there altogether?',128,'There are 56 adults. Twelve families bring two children and sixteen bring three, giving 24+48=72 children. Total 56+72=128.','FRAC-04',check=28*2+12*2+16*3))
 p.append(item('Three rotating signs return to their starting positions after 8, 18 and 24 seconds respectively. If they start aligned, how many seconds until they next align?',72,'The least common multiple uses 2³ from 8 and 3² from 18. It is 8×9=72, which is also divisible by 24.','DIV-02',check=math.lcm(8,18,24)))
 p.append(item('A four-digit number has four different digits. Multiplying it by 9 reverses its digits. What is the original number?',1089,'Write 9×ABCD=DCBA. A must be 1, since a number starting with 2 would produce five digits. The units equation makes D=9 and gives carry 8. The thousands column then has no incoming carry, so the hundreds column satisfies 9B+u=C<10. As B cannot repeat A=1, B=0 and C=u. The tens column is 9C+8=10u. Hence C=u=8. The number is 1089, and 1089×9=9801.','DIG-05',check=next(n for n in range(1000,1112) if str(9*n)==str(n)[::-1] and len(set(str(n)))==4)))
 p.append(item('A cube is made from 216 unit cubes. Its top and four vertical sides are painted, but its bottom is not. How many unit cubes receive no paint?',80,'Since 216=6³, the cube is six units along every edge. Unpainted cubes avoid four side layers and the top but may reach the bottom. The count is (6−2)(6−2)(6−1)=4×4×5=80.','SOLID-02',check=(6-2)**2*(6-1),figure=cuboid(6,6,6)))
 p.append(item('A jar is half full of marbles. After 18 marbles are added it is five sixths full. How many more marbles are needed to fill it completely?',9,'The 18 added marbles represent 5/6−1/2=1/3 of the jar, so its capacity is 54. The remaining sixth is 54÷6=9 marbles.','FRAC-01',check=int(F(18)/(F(5,6)-F(1,2))/6)))
 return [one,two,paper('rossmoyne',6,p)]
